export class BattleAudio{
  constructor(enabled=true){this.enabled=enabled;this.ctx=null;this.nextBeat=0;this.beat=0;this.noise=null;}
  async start(){if(!this.enabled)return;try{if(!this.ctx){const AudioCtx=window.AudioContext||window.webkitAudioContext;this.ctx=new AudioCtx();this.master=this.ctx.createGain();this.master.gain.value=.16;this.master.connect(this.ctx.destination);this.noise=this.ctx.createBuffer(1,this.ctx.sampleRate,this.ctx.sampleRate);const data=this.noise.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=Math.random()*2-1;}if(this.ctx.state==='suspended')await this.ctx.resume();}catch{}}
  tone(freq,duration=.15,gain=.4,type='sine',slide=0){if(!this.enabled||!this.ctx||this.ctx.state!=='running')return;const t=this.ctx.currentTime,o=this.ctx.createOscillator(),g=this.ctx.createGain();o.type=type;o.frequency.setValueAtTime(freq,t);if(slide)o.frequency.exponentialRampToValueAtTime(slide,t+duration);g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(gain,t+.008);g.gain.exponentialRampToValueAtTime(.0001,t+duration);o.connect(g);g.connect(this.master);o.start(t);o.stop(t+duration+.02);}
  hiss(duration=.15,gain=.3,freq=1700){if(!this.enabled||!this.ctx||this.ctx.state!=='running')return;const t=this.ctx.currentTime,n=this.ctx.createBufferSource(),filter=this.ctx.createBiquadFilter(),g=this.ctx.createGain();n.buffer=this.noise;filter.type='bandpass';filter.frequency.value=freq;filter.Q.value=.7;g.gain.setValueAtTime(gain,t);g.gain.exponentialRampToValueAtTime(.0001,t+duration);n.connect(filter);filter.connect(g);g.connect(this.master);n.start(t);n.stop(t+duration);}
  events(events){let shots=0;for(const e of events){if(e.type==='fire'&&shots++<2){if(e.kind==='sword'){this.hiss(.18,.32,2400);this.tone(500,.14,.16,'sine',130);}else if(e.kind==='laser'||e.kind==='railgun')this.tone(1300,.13,.13,'sawtooth',190);else if(e.kind==='missile')this.hiss(.24,.22,800);else{this.tone(e.kind==='cannon'?82:160,.14,.32,'triangle',45);this.hiss(.07,.3,2000);}}if(e.type==='destroy'||e.type==='break'){this.hiss(.7,.9,350);this.tone(95,.5,.5,'sawtooth',25);}if(e.type==='hit'&&shots<3)this.tone(290,.045,.08,'triangle',80);}}
  update(battle){if(!this.enabled||!this.ctx||this.ctx.state!=='running'||!battle||battle.result)return;const t=this.ctx.currentTime;if(t<this.nextBeat)return;this.nextBeat=t+.42;const notes=[55,55,65.4,55,73.4,55,82.4,65.4];this.tone(notes[this.beat%8],.35,.13,'triangle');if(this.beat%4===0)this.tone(110,.75,.055,'sine');this.beat++;}
  result(won){for(let i=0;i<3;i++)setTimeout(()=>this.tone(won?[330,440,660][i]:[220,165,110][i],.38,.25,'triangle'),i*130);}
  setEnabled(enabled){this.enabled=enabled;if(this.master)this.master.gain.value=enabled?.16:0;if(enabled)this.start();}
}
